mapper.select:
SELECT id, wallet_id, user_type, user_id, biz_type, amount, direction, balance_after,
       source, status, biz_no, peer_txn_id, remark, create_time
FROM wallet_transaction
WHERE user_type = #{userType} AND user_id = #{userId}

    AND biz_type = #{bizType}

ORDER BY create_time DESC, id DESC
